//! operation 级 TypeScript client 渲染。
//!
//! 生成物不 import 任何 Hermes npm 包：只声明一个 `HermesTransport` 结构接口，
//! 由宿主运行时绑定传入，浏览器路径可接 Web `fetch`。method 级 delegate 要等
//! 上游 method projection，本阶段只生成 operation 级调用。

use crate::{
    bindings::Bindings,
    plan::{FileOwnership, GeneratedFile},
};

/// 生成路径（相对生成根目录）。
pub(crate) const CLIENT_PATH: &str = "hermes/operations.ts";

/// 渲染 client 模块。
pub(crate) fn render(bindings: &Bindings) -> GeneratedFile {
    let mut out = String::new();
    out.push_str(
        "// Generated by `hermes-generator` from a `vos-operation-contract-v0` /\n\
         // `operation-syntax-projection` artifact. Do not edit by hand.\n\n",
    );
    out.push_str(
        "export interface HermesTransport {\n\
         \x20 dispatch(operationId: string, params: unknown): Promise<unknown>;\n\
         }\n\n",
    );

    out.push_str("export const operationIds = {\n");
    for operation in &bindings.operations {
        out.push_str(&format!("  {}: \"{}\",\n", operation.method_name, operation.operation_id));
    }
    out.push_str("} as const;\n\n");
    out.push_str("export type OperationName = keyof typeof operationIds;\n\n");

    for operation in &bindings.operations {
        if operation.params.is_empty() {
            out.push_str(&format!("export type {} = Record<string, never>;\n\n", operation.params_type()));
        }
        else {
            out.push_str(&format!("export type {} = {{\n", operation.params_type()));
            for parameter in &operation.params {
                out.push_str(&format!("  {}: {};\n", parameter.key, parameter.ts_type));
            }
            out.push_str("};\n\n");
        }
        out.push_str(&format!("export type {} = {};\n\n", operation.result_type(), operation.result));
    }

    out.push_str("export interface HermesClient {\n");
    for operation in &bindings.operations {
        out.push_str(&format!(
            "  {}(params: {}): Promise<{}>;\n",
            operation.method_name,
            operation.params_type(),
            operation.result_type()
        ));
    }
    out.push_str("}\n\n");

    out.push_str("export function createHermesClient(transport: HermesTransport): HermesClient {\n  return {\n");
    for operation in &bindings.operations {
        out.push_str(&format!(
            "    {}: (params) => transport.dispatch(operationIds.{}, params) as Promise<{}>,\n",
            operation.method_name,
            operation.method_name,
            operation.result_type()
        ));
    }
    out.push_str("  };\n}\n");

    GeneratedFile::new(CLIENT_PATH, out, FileOwnership::Generated)
}
